	/* @Override */
	public void dataTypeReplaced(DataType oldDt, DataType newDt) {
		if (deleting) {
			return;
		}
		using (Closeable c = @lock.write())
{
			checkDeleted();
			if (oldDt == getDataType()) {
				DataTypeUtilities.checkValidReplacement(oldDt, newDt);
				if (newDt == this) {
					newDt = DataType.DEFAULT;
				}
				settingsDef = null;
				defaultSettings = null;
				oldDt.removeParent(this);
				newDt = resolve(newDt);
				newDt.addParent(this);
				record.setLongValue(TypedefDBAdapter.TYPEDEF_DT_ID_COL,
					dataMgr.getResolvedID(newDt));
				try {
					adapter.updateRecord(record, true);
				}
				catch (IOException e) {
					dataMgr.dbError(e);
				}
				if (oldDt.getLength() != newDt.getLength()) {
					notifySizeChanged(false);
				}
				else if (oldDt.getAlignment() != newDt.getAlignment()) {
					notifyAlignmentChanged(false);
				}
				else {
					dataMgr.dataTypeChanged(this, false);
				}
			}
		}
	}

