	/* @Override */
	protected bool refresh(DBRecord rec) {
		try {
			if (rec == null) {
				rec = adapter.getRecord(key);
			}
			if (rec != null) {
				settingsDef = null;
				record = rec;
				completeRefresh();
				return true;
			}
		}
		catch (IOException e) {
			dataMgr.dbError(e);
		}
		return false;
	}

	/* @Override */
	public SettingsDefinition[] getSettingsDefinitions() {
		using (Closeable c = @lock.read())
{
			refreshIfNeeded();
			if (settingsDef == null) {
				DataType dt = getDataType();
				SettingsDefinition[] settingsDefinitions = dt.getSettingsDefinitions();
				TypeDefSettingsDefinition[] typeDefSettingsDefinitions =
					dt.getTypeDefSettingsDefinitions();
				settingsDef = new SettingsDefinition[settingsDefinitions.length +
					typeDefSettingsDefinitions.length];
				Array.Copy(settingsDefinitions, 0, settingsDef, 0,
					settingsDefinitions.length);
				Array.Copy(typeDefSettingsDefinitions, 0, settingsDef,
					settingsDefinitions.length, typeDefSettingsDefinitions.length);
			}
			return settingsDef;
		}
	}

